X=np.load('pass_1/pooled.npy');p=practice()[:768]
y=np.array([LABELS.index(x['label']) for x in p])
def fit(X,y,lam,mode):
    Y=np.eye(8)[y]
    mu=X.mean(0)
    Xc=X-mu
    if mode=='ridge':
        Wt=np.linalg.solve(Xc.T@Xc+lam*np.eye(768),Xc.T@(Y-Y.mean(0)))
        return Wt.T, Y.mean(0)@np.ones(8)*0+ (Y.mean(0)-Wt.T@mu)
for lam in [0.1,1,3,10,30,100]:
    Wc,b=fit(X[:600],y[:600],lam,'ridge')
    print(lam,((X[600:]@Wc.T+b).argmax(1)==y[600:]).mean(),((X[:600]@Wc.T+b).argmax(1)==y[:600]).mean())
